{"command":"create","file_text":""""Collect energies from all optimization results and compute formation energies."""
import json, os, glob
from ase.io import read

systems = ["NFPP_pristine", "NFPP_Mn", "NFPP_Co", "NFPP_Mg", "NFPP_Cr"]
refs = ["ref_Fe", "ref_Mn", "ref_Co", "ref_Mg", "ref_Cr"]

energies = {}
volumes = {}
lattice_params = {}

for s in systems + refs:
    rdir = f"results_{s}"
    rjson = os.path.join(rdir, "result.json")
    if os.path.exists(rjson):
        with open(rjson) as f:
            data = json.load(f)
        energies[s] = data.get("energy", data.get("total_energy", None))
        # Try to read optimized structure for volume
        opt_files = glob.glob(os.path.join(rdir, "*_optimized.cif"))
        if opt_files:
            atoms = read(opt_files[0])
            volumes[s] = atoms.get_volume()
            cell = atoms.get_cell()
            lattice_params[s] = {
                "a": cell.lengths()[0],
                "b": cell.lengths()[1],
                "c": cell.lengths()[2],
            }
    else:
        print(f"WARNING: No result.json for {s}")

print("\n=== Raw Energies (eV) ===")
for k, v in energies.items():
    print(f"  {k}: {v:.4f}")

# Per-atom reference energies
ref_per_atom = {}
for elem in ["Fe", "Mn", "Co", "Mg", "Cr"]:
    key = f"ref_{elem}"
    if key in energies:
        rdir = f"results_{key}"
        opt_files = glob.glob(os.path.join(rdir, "*_optimized.cif"))
        if opt_files:
            atoms = read(opt_files[0])
            ref_per_atom[elem] = energies[key] / len(atoms)
        else:
            ref_per_atom[elem] = energies[key]  # single atom

print("\n=== Reference per-atom energies (eV/atom) ===")
for k, v in ref_per_atom.items():
    print(f"  {k}: {v:.4f}")

# Formation energy of doping:
# E_f = E(NFPP_X) - E(NFPP_pristine) - mu_X + mu_Fe
# where mu_X = per-atom energy of dopant, mu_Fe = per-atom energy of Fe
print("\n=== Doping Formation Energies ===")
dopants = {"Mn": "NFPP_Mn", "Co": "NFPP_Co", "Mg": "NFPP_Mg", "Cr": "NFPP_Cr"}
results = {}
for d, skey in dopants.items():
    if skey in energies and "NFPP_pristine" in energies:
        Ef = (energies[skey] - energies["NFPP_pristine"]
              - ref_per_atom[d] + ref_per_atom["Fe"])
        results[d] = {
            "formation_energy_eV": round(Ef, 4),
            "doped_total_energy_eV": round(energies[skey], 4),
            "volume_A3": round(volumes.get(skey, 0), 2),
            "lattice": lattice_params.get(skey, {}),
        }
        print(f"  {d}: E_f = {Ef:.4f} eV")

# Volume changes
print("\n=== Volume Changes ===")
V0 = volumes.get("NFPP_pristine", 0)
print(f"  Pristine: {V0:.2f} Å³")
for d, skey in dopants.items():
    if skey in volumes:
        dV = (volumes[skey] - V0) / V0 * 100
        results[d]["volume_change_pct"] = round(dV, 3)
        print(f"  {d}: {volumes[skey]:.2f} Å³ (ΔV = {dV:+.3f}%)")

# Lattice parameter changes
print("\n=== Lattice Parameter Changes ===")
lp0 = lattice_params.get("NFPP_pristine", {})
print(f"  Pristine: a={lp0.get('a',0):.4f}, b={lp0.get('b',0):.4f}, c={lp0.get('c',0):.4f}")
for d, skey in dopants.items():
    lp = lattice_params.get(skey, {})
    da = (lp.get('a',0) - lp0.get('a',0)) / lp0.get('a',1) * 100
    db = (lp.get('b',0) - lp0.get('b',0)) / lp0.get('b',1) * 100
    dc = (lp.get('c',0) - lp0.get('c',0)) / lp0.get('c',1) * 100
    results[d]["lattice_change_pct"] = {"da": round(da,3), "db": round(db,3), "dc": round(dc,3)}
    print(f"  {d}: Δa={da:+.3f}%, Δb={db:+.3f}%, Δc={dc:+.3f}%")

# Save summary
summary = {
    "pristine": {
        "total_energy_eV": round(energies.get("NFPP_pristine", 0), 4),
        "volume_A3": round(V0, 2),
        "lattice": {k: round(v, 4) for k, v in lp0.items()},
    },
    "dopants": results,
    "ref_per_atom_eV": {k: round(v, 4) for k, v in ref_per_atom.items()},
}
with open("doping_analysis.json", "w") as f:
    json.dump(summary, f, indent=2)
print("\nSaved doping_analysis.json")
